import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"56、【旅】 艮下離上","description":"子夏易傳 - 56、【旅】 艮下離上","frontmatter":{"title":"56、【旅】 艮下離上","description":"子夏易傳 - 56、【旅】 艮下離上"},"headers":[],"relativePath":"classics/zixia/058.md","filePath":"classics/zixia/058.md"}'),i={name:"classics/zixia/058.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_56、【旅】-艮下離上" tabindex="-1">56、【旅】 艮下離上 <a class="header-anchor" href="#_56、【旅】-艮下離上" aria-label="Permalink to “56、【旅】 艮下離上”">​</a></h1><p>卦辭：旅小亨。旅，貞吉。</p><p>彖曰：旅小亨。柔得中乎外，而順乎剛，止而麗乎明，是以小亨。旅貞吉也。旅之時義大矣哉。</p><p>子夏：雖柔中得乎外，下而順於艮剛。上不能有其上，而寄旅於下，下不事其上，而不應於上，旅之義也。柔得中附順於下剛，而剛不距是以小亨。旅之為道，不敢妄動，上麗其明乃可止也。止不妄也。明辨也。不為物疑，故正吉也。旅之為道，貞吉而後極，旅小亨。故再雲旅非大人不能安其旅，而獲其小亨也。</p><p>象曰：山上有火，旅。君子以明愼用刑，而不留獄。</p><p>子夏：火寄於山，火非可久刑以正法。刑不可久，故明愼用刑，以寄治之，而不留獄。</p><p>初六，旅瑣瑣，斯其所取災。</p><p>象曰：旅瑣瑣，志窮，災也。</p><p>子夏：柔而在下，瑣瑣賤旅也。有應於上，滿而得志，斯極之矣。以賤役而自盈，斯自取其災也。</p><p>六二，旅即次，懷其資，得童僕，貞。</p><p>象曰：得童僕，貞。終無尤也。</p><p>子夏：守位奉上，而三相與得，其次來其資也。奉上而得中，得童僕之貞也。終何尤矣。</p><p>九三，旅焚其次，喪其童僕，貞厲。</p><p>象曰：旅焚其次，亦以傷矣以。旅與下其義，喪也。</p><p>（原本闕傳）</p><p>九四，旅於處，得其資斧，我心不快。</p><p>象曰：旅於處，未得位也。得其資斧，心未快也。</p><p>子夏：旅以剛而升於上，體寄得所處，未得位也。資斧者，將營作所使之具也。得其所處下，應而獲其資器，而以旅之難也。其可就乎終不得其位，故我心不快也。</p><p>六五，射雉，一矢亡。終以譽命。</p><p>象曰：終以譽命，上逮也。</p><p>子夏：君子藏器於身，待時而動，則我由獲也。旅，火山旅也。五寄柔於剛也，物有非可久也。不由於我也，豈久其位乎。將遂安也，非惟失位，抑亦喪其謀矣。以其居中上之位，旅之貴者也，素以眾仰，故及於終有譽之命也。欲麗中，故曰雉也。</p><p>上九，鳥焚其巢，旅人先笑，後號咷。喪牛於易，兇。</p><p>象曰：以旅在上，其義焚也。喪牛於易，終莫之聞也。</p><p>子夏：旅於上，極巢之髙也。旅得上位，先笑者也。以旅在上，人所嫉也。則焚巢而號咷矣。牛順物也，旅之為道，全於順也。剛而亢居，喪其順也。旅者人之客也，又剛而無順人，何吉哉，故喪於無難也。固其兇哉。</p>',24)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
